=== src/main/java/PolicyBasePremium.java
import java.util.List;
import java.util.stream.Collectors;

/**
 * The base premium the MHPCO tariffs a whole quote at.
 *
 * <p>Knows that the items of a quote are tariffed in groups of alike items and
 * that the policy base premium is the sum over those groups. Defers what a
 * group of alike items costs to the MHPCO's building block offer, and knows
 * nothing about the surcharges, discounts and the processing fee that turn a
 * base premium into a premium.
 *
 * <p>Holds the MHPCO's reading of "alike": items are alike when they are of
 * the same type, not merely of the same family. Two runes and a moonstone are
 * therefore two groups, not one group of gemstone-y things.
 */
final class PolicyBasePremium {

    private PolicyBasePremium() {
    }

    static int of(List<Item> items) {
        return items.stream()
                .collect(Collectors.groupingBy(Item::type))
                .values().stream()
                .mapToInt(BuildingBlock::basePremiumFor)
                .sum();
    }
}
=== src/main/java/PolicyModifiers.java
/**
 * The policy-wide modifiers the MHPCO applies to a policy base premium.
 *
 * <p>Unlike the item-specific risk surcharges, these follow from the customer's
 * standing with the MHPCO rather than from any insured item, and they are
 * measured against the policy base premium, the sum of all item base premiums.
 */
final class PolicyModifiers {

    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    private static final int LOYALTY_FROM_YEARS = 2;
    private static final int PERCENT = 100;

    private PolicyModifiers() {
    }

    static int of(Customer customer, int policyBasePremium) {
        return -loyaltyDiscountFor(customer, policyBasePremium);
    }

    private static int loyaltyDiscountFor(Customer customer, int policyBasePremium) {
        if (customer.yearsWithMHPCO() < LOYALTY_FROM_YEARS) {
            return 0;
        }
        return policyBasePremium * LOYALTY_DISCOUNT_PERCENT / PERCENT;
    }
}
=== src/main/java/PremiumCalculator.java
import java.util.List;

/**
 * Assembles the MHPCO premium for the items of a quote.
 *
 * <p>Knows that a premium is the policy base premium plus the risk surcharges
 * the insured items carry plus the processing fee charged on every premium;
 * defers what the items of a quote are tariffed at to the policy base premium,
 * and knows nothing about JSON or the command line.
 */
final class PremiumCalculator {

    private static final int PROCESSING_FEE_IN_G = 5;

    private PremiumCalculator() {
    }

    static int premiumFor(Customer customer, List<Item> items) {
        int policyBasePremium = PolicyBasePremium.of(items);
        return policyBasePremium
                + RiskSurcharges.of(items)
                + PolicyModifiers.of(customer, policyBasePremium)
                + PROCESSING_FEE_IN_G;
    }
}
=== src/main/java/PriceList.java
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium each kind of item is tariffed at.
 *
 * <p>The MHPCO tariffs main items individually and components as a category:
 * every component carries the same base premium, whatever it is made of.
 *
 * <p>Changes whenever the MHPCO revises its tariff or takes on a new kind of
 * item; knows nothing about how a premium is assembled from those amounts.
 */
final class PriceList {

    private static final int SWORD_BASE_PREMIUM_IN_G = 100;
    private static final int AMULET_BASE_PREMIUM_IN_G = 60;
    private static final int STAFF_BASE_PREMIUM_IN_G = 80;
    private static final int POTION_BASE_PREMIUM_IN_G = 40;

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private static final int NOT_TARIFFED = 0;

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS_IN_G = Map.of(
            "sword", SWORD_BASE_PREMIUM_IN_G,
            "amulet", AMULET_BASE_PREMIUM_IN_G,
            "staff", STAFF_BASE_PREMIUM_IN_G,
            "potion", POTION_BASE_PREMIUM_IN_G);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private PriceList() {
    }

    static int basePremiumFor(Item item) {
        if (isComponent(item)) {
            return COMPONENT_BASE_PREMIUM_IN_G;
        }
        return MAIN_ITEM_BASE_PREMIUMS_IN_G.getOrDefault(item.type(), NOT_TARIFFED);
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }
}
=== src/main/java/RiskSurcharges.java
import java.util.List;

/**
 * The item-specific risk surcharges the MHPCO levies on the items of a quote.
 *
 * <p>Holds the MHPCO's reading of the scope question: an item-specific
 * surcharge is a percentage of the base premium of the affected item, not of
 * the policy base premium. The surcharges of a quote are therefore the sum,
 * over its items, of every recognised risk that item carries. Defers which
 * risks exist and what each costs to the MHPCO's list of insurable risks.
 *
 * <p>Changes whenever the MHPCO revises how an item-specific surcharge is
 * measured or accumulated; knows nothing about the policy-wide modifiers
 * (loyalty, first insurance, follow-up contract), which apply to the policy
 * base premium.
 */
final class RiskSurcharges {

    private static final int PERCENT = 100;

    private RiskSurcharges() {
    }

    static int of(List<Item> items) {
        return items.stream().mapToInt(RiskSurcharges::surchargesOn).sum();
    }

    private static int surchargesOn(Item item) {
        return InsurableRisk.carriedBy(item).stream()
                .mapToInt(risk -> percentOfBasePremium(item, risk.surchargePercent()))
                .sum();
    }

    private static int percentOfBasePremium(Item item, int percent) {
        return PriceList.basePremiumFor(item) * percent / PERCENT;
    }
}
=== src/main/java/ScenarioJson.java
import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;

/**
 * Translates between the MHPCO wire format and the domain.
 *
 * <p>Changes whenever the JSON schema of a scenario or of a results document
 * changes; knows nothing about tariffs, premiums or the command line.
 */
final class ScenarioJson {

    private ScenarioJson() {
    }

    static List<Item> itemsOfFirstQuote(JsonNode scenario) {
        return itemsOf(scenario.get("steps").get(0));
    }

    private static List<Item> itemsOf(JsonNode quoteStep) {
        List<Item> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new Item(item.get("type").asText(), item.path("enchantment").asInt(),
                    item.path("cursed").asBoolean()));
        }
        return items;
    }

    static Customer customerOf(JsonNode scenario) {
        return new Customer(scenario.get("customer").get("yearsWithMHPCO").asInt());
    }

    static String quoteResults(int premium) {
        return "{\"results\":[{\"premium\":" + premium + "}]}";
    }
}

